/* Hidden attribute priority rule */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1a1c23;
  --card-bg: #282a36;
  --primary: #50fa7b;
  --primary-hover: #3dd665;
  --primary-active: #2bb050;
  --secondary: #ff79c6;
  --secondary-hover: #e063b0;
  --text-main: #f8f8f2;
  --text-dim: #bd93f9;
  --error-color: #ff5555;
  --border-color: #44475a;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.game-container {
  width: 100%;
  max-width: 480px;
  background-color: var(--card-bg);
  border: 2px solid var(--border-color);
  border-radius: 8px;
  padding: 1.5rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.game-header {
  text-align: center;
}

.game-title {
  font-size: 1.6rem;
  color: var(--primary);
  letter-spacing: 0.05em;
}

.game-subtitle {
  color: var(--text-dim);
  font-size: 0.95rem;
  margin-top: 0.25rem;
}

.score-board {
  display: flex;
  justify-content: space-between;
  background-color: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 0.75rem 1rem;
  gap: 0.5rem;
}

.stat-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
}

.stat-label {
  font-size: 0.8rem;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.stat-value {
  font-size: 1.25rem;
  font-weight: 700;
}

.stat-value.highlight {
  color: var(--secondary);
  word-break: break-all;
}

.target-hint {
  font-size: 1rem;
  text-align: center;
  margin-bottom: 0.75rem;
  color: var(--text-main);
}

.target-hint strong {
  color: var(--primary);
  font-size: 1.15rem;
}

.input-group {
  display: flex;
  gap: 0.5rem;
}

.text-input {
  flex: 1;
  min-width: 0;
  padding: 0.65rem 0.85rem;
  font-size: 1rem;
  background-color: var(--bg-color);
  border: 2px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-main);
  outline: none;
  transition: border-color 0.2s;
}

.text-input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px rgba(80, 250, 123, 0.25);
}

.btn {
  padding: 0.65rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  transition: background-color 0.15s, transform 0.1s, box-shadow 0.15s;
  white-space: nowrap;
}

.btn:focus-visible {
  outline: 2px solid var(--text-main);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: var(--primary);
  color: #111217;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-primary:active {
  background-color: var(--primary-active);
}

.btn-secondary {
  background-color: transparent;
  color: var(--text-dim);
  border: 1px solid var(--border-color);
  width: 100%;
}

.btn-secondary:hover {
  background-color: rgba(189, 147, 249, 0.1);
  color: var(--text-main);
  border-color: var(--text-dim);
}

.message-area {
  min-height: 1.5rem;
  margin-top: 0.5rem;
  font-size: 0.95rem;
  font-weight: 500;
  text-align: center;
}

.message-area.error {
  color: var(--error-color);
}

.message-area.success {
  color: var(--primary);
}

.history-section {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.history-title {
  font-size: 0.9rem;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.word-list {
  list-style-position: inside;
  background-color: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 0.75rem 1rem;
  max-height: 150px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.word-item {
  font-family: monospace;
  font-size: 1rem;
  color: var(--text-main);
}

@media (max-width: 400px) {
  .game-container {
    padding: 1rem;
  }

  .input-group {
    flex-direction: column;
  }

  .btn {
    width: 100%;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const START_WORD = 'pixel';
  let chain = [START_WORD];
  let usedWords = new Set([START_WORD]);

  const chainCounterEl = document.getElementById('chain-counter');
  const currentWordEl = document.getElementById('current-word');
  const requiredLetterEl = document.getElementById('required-letter');
  const wordFormEl = document.getElementById('word-form');
  const wordInputEl = document.getElementById('word-input');
  const messageAreaEl = document.getElementById('message-area');
  const wordListEl = document.getElementById('word-list');
  const resetBtnEl = document.getElementById('reset-btn');

  function getLastWord() {
    return chain[chain.length - 1];
  }

  function getRequiredLetter() {
    const lastWord = getLastWord();
    return lastWord.slice(-1).toLowerCase();
  }

  function updateUI() {
    const lastWord = getLastWord();
    const reqChar = getRequiredLetter();

    chainCounterEl.textContent = chain.length;
    currentWordEl.textContent = lastWord;
    requiredLetterEl.textContent = `'${reqChar.toUpperCase()}'`;
  }

  function showMessage(text, isError = true) {
    messageAreaEl.textContent = text;
    messageAreaEl.className = 'message-area ' + (isError ? 'error' : 'success');
  }

  function clearMessage() {
    messageAreaEl.textContent = '';
    messageAreaEl.className = 'message-area';
  }

  function addWordToHistory(word) {
    const li = document.createElement('li');
    li.className = 'word-item';
    li.textContent = word;
    wordListEl.appendChild(li);
    wordListEl.scrollTop = wordListEl.scrollHeight;
  }

  function handleWordSubmission(e) {
    e.preventDefault();
    clearMessage();

    const rawInput = wordInputEl.value.trim();
    const word = rawInput.toLowerCase();

    if (!word) {
      showMessage('Please enter a word.');
      wordInputEl.focus();
      return;
    }

    if (!/^[a-z]+$/i.test(word)) {
      showMessage('Words can only contain alphabetic letters.');
      wordInputEl.focus();
      return;
    }

    const expectedLetter = getRequiredLetter();
    const firstLetter = word[0];

    if (firstLetter !== expectedLetter) {
      showMessage(`Word must begin with '${expectedLetter.toUpperCase()}'.`);
      wordInputEl.focus();
      return;
    }

    if (usedWords.has(word)) {
      showMessage('Already used');
      wordInputEl.focus();
      return;
    }

    // Valid word accepted
    usedWords.add(word);
    chain.push(word);
    addWordToHistory(word);
    updateUI();

    showMessage(`'${word}' accepted!`, false);
    wordInputEl.value = '';
    wordInputEl.focus();
  }

  function resetGame() {
    chain = [START_WORD];
    usedWords = new Set([START_WORD]);

    wordListEl.innerHTML = '';
    addWordToHistory(START_WORD);

    updateUI();
    clearMessage();
    wordInputEl.value = '';
    wordInputEl.focus();
  }

  wordFormEl.addEventListener('submit', handleWordSubmission);
  resetBtnEl.addEventListener('click', resetGame);

  // Initialize on load
  updateUI();
  wordInputEl.focus();
});
